/** One tool call waiting on a person: what it does, which agent asked, why, and the change as before/after text. */
export type ApprovalRecord = {
  id: string;
  title: string;
  tool: string;
  kind: ApprovalKind;
  agent: string;
  reason: string;
  files: { path: string; before?: string; after: string }[];
